/**
 * Combat audio. Plays short recorded-style samples from /sfx (generated by
 * blender/film/sfx_export.py), with slight random pitch so repeated hits do
 * not sound mechanical, and simple left/right panning. Falls back to the
 * original oscillator tones until the samples have loaded.
 */

const SAMPLES = ["slash-1", "slash-2", "slash-3", "clash", "parry", "hit", "leap", "power", "fold", "draw", "step", "win", "lose"] as const;
type Sample = (typeof SAMPLES)[number];

const MASTER = 0.5;

export class AudioBus {
  ctx: AudioContext | null = null;
  muted = false;
  private master: GainNode | null = null;
  private wind: OscillatorNode | null = null;
  private windG: GainNode | null = null;
  private buffers = new Map<Sample, AudioBuffer>();
  private loading = false;
  private lastStep = 0;
  private slashIdx = 0;

  unlock() {
    if (this.ctx) {
      void this.ctx.resume();
      return;
    }
    const C = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    this.ctx = new C();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : MASTER;
    this.master.connect(this.ctx.destination);
    this.startWind();
    void this.load();
  }

  private async load() {
    if (this.loading || !this.ctx) return;
    this.loading = true;
    const ctx = this.ctx;
    await Promise.all(
      SAMPLES.map(async (name) => {
        try {
          const res = await fetch(`/sfx/${name}.mp3`);
          if (!res.ok) return;
          const data = await res.arrayBuffer();
          const buf = await ctx.decodeAudioData(data);
          this.buffers.set(name, buf);
        } catch {
          /* keep the oscillator fallback for this sound */
        }
      }),
    );
  }

  setMuted(v: boolean) {
    this.muted = v;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(v ? 0 : MASTER, this.ctx.currentTime, 0.05);
  }

  private startWind() {
    if (!this.ctx || !this.master) return;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = "sine";
    o.frequency.value = 70;
    g.gain.value = 0.015;
    o.connect(g);
    g.connect(this.master);
    o.start();
    this.wind = o;
    this.windG = g;
  }

  /** Play a sample; returns false when it is not loaded (caller may fall back). */
  private play(name: Sample, gain = 1, pan = 0, pitchVar = 0.06): boolean {
    const buf = this.buffers.get(name);
    if (!this.ctx || !this.master || !buf || this.muted) return !!buf;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = 1 + (Math.random() * 2 - 1) * pitchVar;
    const g = this.ctx.createGain();
    g.gain.value = gain;
    let node: AudioNode = g;
    if (pan && this.ctx.createStereoPanner) {
      const p = this.ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      g.connect(p);
      node = p;
    }
    node.connect(this.master);
    src.connect(g);
    src.start();
    return true;
  }

  private tone(freq: number, dur: number, type: OscillatorType, gain = 0.12, slide = 0) {
    if (!this.ctx || !this.master || this.muted) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t + dur);
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g);
    g.connect(this.master);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  slash(pan = 0) {
    this.slashIdx = (this.slashIdx + 1 + Math.floor(Math.random() * 2)) % 3;
    const name = (["slash-1", "slash-2", "slash-3"] as const)[this.slashIdx];
    if (this.play(name, 0.75, pan, 0.08)) return;
    this.tone(420, 0.12, "sawtooth", 0.08, -220);
    this.tone(1200, 0.06, "square", 0.04, -800);
  }
  clash(pan = 0) {
    if (this.play("clash", 0.9, pan)) return;
    this.tone(180, 0.18, "square", 0.16, -80);
    this.tone(90, 0.22, "sawtooth", 0.1, 40);
  }
  hit(pan = 0) {
    if (this.play("hit", 1, pan, 0.1)) {
      this.play("clash", 0.18, pan, 0.15);
      return;
    }
    this.tone(90, 0.16, "sine", 0.18, -40);
  }
  parry(pan = 0) {
    if (this.play("parry", 0.95, pan)) return;
    this.tone(880, 0.1, "triangle", 0.1, 200);
  }
  leap(pan = 0) {
    this.play("leap", 0.6, pan, 0.08);
  }
  power(pan = 0) {
    this.play("power", 0.8, pan, 0.04);
  }
  draw() {
    this.play("draw", 0.8, 0, 0.02);
  }
  /** Footsteps, rate-limited so they follow stride rather than frame rate. */
  step(t: number, pan = 0, speed = 1) {
    const gap = 0.34 / Math.max(0.6, speed);
    if (t - this.lastStep < gap) return;
    this.lastStep = t;
    this.play("step", 0.35, pan, 0.12);
  }
  fold() {
    if (this.play("fold", 0.7, 0, 0.02)) return;
    this.tone(220, 0.4, "sine", 0.1, -120);
    this.tone(55, 0.6, "triangle", 0.08, 20);
  }
  win() {
    if (this.play("win", 0.9, 0, 0)) return;
    this.tone(440, 0.2, "triangle", 0.1, 80);
    this.tone(660, 0.28, "sine", 0.08, 40);
  }
  lose() {
    if (this.play("lose", 0.9, 0, 0)) return;
    this.tone(160, 0.5, "sawtooth", 0.1, -100);
  }
  tick(t: number) {
    if (this.wind && this.ctx) this.wind.frequency.setTargetAtTime(62 + Math.sin(t * 0.3) * 8, this.ctx.currentTime, 0.2);
  }
}
